interface StablePool3Coins:
    def add_liquidity(amounts: uint256[3], min_mint_amount: uint256): payable
    def remove_liquidity(amount: uint256, min_amounts: uint256[3]): nonpayable


interface LendingStablePool3Coins:
    def add_liquidity(
        amounts: uint256[3], min_mint_amount: uint256, use_underlying: bool
    ): payable
    def remove_liquidity_one_coin(
        token_amount: uint256,
        i: int128,
        min_amount: uint256,
        use_underlying: bool,
    ): nonpayable


interface StablePool4Coins:
    def add_liquidity(amounts: uint256[4], min_mint_amount: uint256): payable
    def remove_liquidity(amount: uint256, min_amounts: uint256[4]): nonpayable


interface StableNgPool:
    def exchange(i: int128, j: int128, dx: uint256, min_dy: uint256): payable
    def exchange_underlying(
        i: int128, j: int128, dx: uint256, min_dy: uint256
    ): payable
    def add_liquidity(
        amounts: DynArray[uint256, 8], min_mint_amount: uint256
    ): payable
    def remove_liquidity(
        amount: uint256, min_amounts: DynArray[uint256, 8]
    ): nonpayable
    def remove_liquidity_one_coin(
        token_amount: uint256, i: int128, min_amount: uint256
    ): nonpayable


interface CryptoPool:
    def exchange(i: uint256, j: uint256, dx: uint256, min_dy: uint256): payable
    def exchange_underlying(
        i: uint256, j: uint256, dx: uint256, min_dy: uint256
    ): payable
    def remove_liquidity_one_coin(
        token_amount: uint256, i: uint256, min_amount: uint256
    ): nonpayable


interface CryptoPoolETH:
    def exchange(
        i: uint256, j: uint256, dx: uint256, min_dy: uint256, use_eth: bool
    ): payable


interface TwocryptoNgPool:
    def exchange(
        i: uint256, j: uint256, dx: uint256, min_dy: uint256, receiver: address
    ): payable
    def add_liquidity(
        amounts: uint256[2], min_mint_amount: uint256, receiver: address
    ): payable
    def remove_liquidity(
        amount: uint256, min_amounts: uint256[2], receiver: address
    ): nonpayable
    def remove_liquidity_one_coin(
        lp_token_amount: uint256,
        i: uint256,
        min_amount: uint256,
        receiver: address,
    ): nonpayable


interface TricryptoNgPool:
    def exchange(
        i: uint256, j: uint256, dx: uint256, min_dy: uint256, use_eth: bool
    ): payable
    def add_liquidity(
        amounts: uint256[3], min_mint_amount: uint256, use_eth: bool
    ): payable
    def remove_liquidity(
        amount: uint256, min_amounts: uint256[3], use_eth: bool
    ): nonpayable
    def remove_liquidity_one_coin(
        token_amount: uint256, i: uint256, min_amount: uint256, use_eth: bool
    ): nonpayable


interface Llamma:
    def exchange(
        i: uint256, j: uint256, in_amount: uint256, min_amount: uint256
    ) -> uint256[2]: nonpayable


interface WETH:
    def deposit(): payable
    def withdraw(amount: uint256): nonpayable


interface stETH:
    def submit(referral: address): payable


interface frxETHMinter:
    def submit(): payable


interface wstETH:
    def wrap(stETH_amount: uint256) -> uint256: nonpayable
    def unwrap(wstETH_amount: uint256) -> uint256: nonpayable


interface ERC4626:
    def deposit(assets: uint256, receiver: address) -> uint256: nonpayable
    def redeem(
        shares: uint256, receiver: address, owner: address
    ) -> uint256: nonpayable


interface AmountCallAdapter:
    def deposit(amount: uint256): nonpayable
    def withdraw(amount: uint256): nonpayable


MAX_INPUT_LOSS: constant(uint256) = 5

ETH_ADDRESS: constant(address) = constants.ETH_ADDRESS

version: public(constant(String[8])) = "3.0.0"

is_approved: HashMap[address, HashMap[address, bool]]

WRAPPED_NATIVE_ADDRESS: public(immutable(address))
STETH_ADDRESS: public(immutable(address))
WSTETH_ADDRESS: public(immutable(address))
FRXETH_MINTER_ADDRESS: public(immutable(address))
FRXETH_TOKEN_ADDRESS: public(immutable(address))


event Exchange:
    sender: indexed(address)
    receiver: indexed(address)
    token_in: address
    token_out: address
    amount_in: uint256
    amount_out: uint256


@deploy
def __init__(_wrappers: address[5]):
    WRAPPED_NATIVE_ADDRESS = _wrappers[0]
    STETH_ADDRESS = _wrappers[1]
    WSTETH_ADDRESS = _wrappers[2]
    FRXETH_MINTER_ADDRESS = _wrappers[3]
    FRXETH_TOKEN_ADDRESS = _wrappers[4]

    if WSTETH_ADDRESS != empty(address):
        errors.require(STETH_ADDRESS != empty(address), errors.InitError)

    errors.require(
        (FRXETH_MINTER_ADDRESS == empty(address))
        == (FRXETH_TOKEN_ADDRESS == empty(address)),
        errors.InitError,
    )


@external
@payable
def __default__():
    pass


@external
@view
def WETH_ADDRESS() -> address:
    return WRAPPED_NATIVE_ADDRESS


@internal
@view
def _bal(token: address) -> uint256:
    if token == ETH_ADDRESS:
        return self.balance
    return staticcall IERC20(token).balanceOf(self)


@internal
def _lazy_approve(token: address, spender: address):
    if token == ETH_ADDRESS:
        return
    if self.is_approved[spender][token]:
        return
    assert extcall IERC20(token).approve(
        spender,
        max_value(uint256),
        default_return_value=True,
        skip_contract_check=True,
    )
    self.is_approved[spender][token] = True


@internal
def _settle_input(
    initial_token: address, amount_in: uint256, eth_value: uint256
) -> uint256:
    if initial_token == ETH_ADDRESS:
        errors.require(eth_value == amount_in, errors.EthValueError)
        return amount_in

    errors.require(eth_value == 0, errors.EthValueError)
    bal_before: uint256 = staticcall IERC20(initial_token).balanceOf(self)
    assert extcall IERC20(initial_token).transferFrom(
        msg.sender,
        self,
        amount_in,
        default_return_value=True,
    )
    actual_in: uint256 = (
        staticcall IERC20(initial_token).balanceOf(self) - bal_before
    )
    errors.require(actual_in > 0, errors.TransferInError)
    errors.require(
        amount_in - actual_in <= MAX_INPUT_LOSS, errors.FeeOnTransferError
    )
    return actual_in


@internal
def _payout(final_token: address, amount_out: uint256, receiver: address):
    if final_token == ETH_ADDRESS:
        raw_call(receiver, b"", value=amount_out)
    else:
        assert extcall IERC20(final_token).transfer(
            receiver,
            amount_out,
            default_return_value=True,
        )


@internal
def _zero_amounts_ng(n_coins: uint256) -> DynArray[uint256, 8]:
    return arrays.zero_amounts_ng(n_coins)


@internal
def _execute_step(step: types.Step, amount: uint256) -> uint256:
    before: uint256 = self._bal(step.token_out)

    if step.kind == constants.STEP_SWAP:
        self._call_swap(step, amount)
    elif step.kind == constants.STEP_ADD_LIQ_ONE:
        self._call_add_one(step, amount)
    elif step.kind == constants.STEP_REMOVE_LIQ_ONE:
        self._call_remove_one(step, amount)
    elif step.kind == constants.STEP_WRAP:
        self._call_wrap(step, amount)
    else:
        raw_revert(errors.StepKindError)

    delta: uint256 = self._bal(step.token_out) - before
    errors.require(delta > 0, errors.ZeroOutputError)
    return delta


@internal
def _execute_route(
    steps: DynArray[types.Step, constants.MAX_LINEAR_STEPS],
    route: types.RouteSlice,
    initial_token: address,
    amount_in: uint256,
) -> (address, uint256):
    start: uint256 = route.step_start
    count: uint256 = route.step_count
    errors.require(start + count <= len(steps), errors.RouteBoundsError)

    token: address = initial_token
    amount: uint256 = amount_in
    for idx: uint256 in range(constants.MAX_LINEAR_STEPS):
        if idx >= count:
            break
        step: types.Step = steps[start + idx]
        errors.require(step.token_in == token, errors.RouteTokenError)
        amount = self._execute_step(step, amount)
        token = step.token_out

    return token, amount


@internal
def _call_swap(step: types.Step, amount: uint256):
    in_token: address = step.token_in
    out_token: address = step.token_out
    eth_val: uint256 = amount if in_token == ETH_ADDRESS else 0

    self._lazy_approve(in_token, step.pool)

    if step.variant == constants.SWAP_VARIANT_EXCHANGE:
        if (
            step.pool_type == constants.POOL_STABLE
            or step.pool_type == constants.POOL_STABLE_NG
        ):
            extcall StablePool(step.pool).exchange(
                convert(step.i, int128),
                convert(step.j, int128),
                amount,
                0,
                value=eth_val,
            )
        elif step.pool_type == constants.POOL_TWOCRYPTO_NG:
            extcall TwocryptoNgPool(step.pool).exchange(
                step.i,
                step.j,
                amount,
                0,
                self,
                value=eth_val,
            )
        elif step.pool_type == constants.POOL_TRICRYPTO_NG:
            use_eth: bool = (in_token == ETH_ADDRESS) or (
                out_token == ETH_ADDRESS
            )
            extcall TricryptoNgPool(step.pool).exchange(
                step.i,
                step.j,
                amount,
                0,
                use_eth,
                value=eth_val,
            )
        elif (
            step.pool_type == constants.POOL_TWOCRYPTO
            or step.pool_type == constants.POOL_TRICRYPTO
        ):
            if in_token == ETH_ADDRESS or out_token == ETH_ADDRESS:
                extcall CryptoPoolETH(step.pool).exchange(
                    step.i,
                    step.j,
                    amount,
                    0,
                    True,
                    value=eth_val,
                )
            else:
                extcall CryptoPool(step.pool).exchange(
                    step.i,
                    step.j,
                    amount,
                    0,
                )
        elif step.pool_type == constants.POOL_LLAMMA:
            extcall Llamma(step.pool).exchange(
                step.i,
                step.j,
                amount,
                0,
            )
        else:
            raw_revert(errors.SwapPoolError)
    elif step.variant == constants.SWAP_VARIANT_EXCHANGE_UNDERLYING:
        if (
            step.pool_type == constants.POOL_STABLE
            or step.pool_type == constants.POOL_STABLE_NG
        ):
            extcall StablePool(step.pool).exchange_underlying(
                convert(step.i, int128),
                convert(step.j, int128),
                amount,
                0,
                value=eth_val,
            )
        elif (
            step.pool_type == constants.POOL_TWOCRYPTO
            or step.pool_type == constants.POOL_TRICRYPTO
        ):
            extcall CryptoPool(step.pool).exchange_underlying(
                step.i,
                step.j,
                amount,
                0,
                value=eth_val,
            )
        else:
            raw_revert(errors.SwapPoolError)
    else:
        raw_revert(errors.SwapVariantError)


@internal
def _call_add_one(step: types.Step, amount: uint256):
    in_token: address = step.token_in
    eth_val: uint256 = amount if in_token == ETH_ADDRESS else 0

    self._lazy_approve(in_token, step.pool)

    if step.pool_type == constants.POOL_STABLE_NG:
        amounts_ng: DynArray[uint256, 8] = self._zero_amounts_ng(step.n_coins)
        amounts_ng[step.i] = amount
        extcall StableNgPool(step.pool).add_liquidity(
            amounts_ng, 0, value=eth_val
        )
    elif step.pool_type == constants.POOL_TRICRYPTO_NG:
        amounts3: uint256[3] = [0, 0, 0]
        amounts3[step.i] = amount
        use_eth: bool = eth_val > 0
        extcall TricryptoNgPool(step.pool).add_liquidity(
            amounts3, 0, use_eth, value=eth_val
        )
    elif step.pool_type == constants.POOL_TWOCRYPTO_NG:
        amounts2: uint256[2] = [0, 0]
        amounts2[step.i] = amount
        extcall TwocryptoNgPool(step.pool).add_liquidity(
            amounts2, 0, self, value=eth_val
        )
    elif step.pool_type == constants.POOL_TWOCRYPTO:
        a2c: uint256[2] = [0, 0]
        a2c[step.i] = amount
        extcall StablePool2Coins(step.pool).add_liquidity(a2c, 0, value=eth_val)
    elif step.pool_type == constants.POOL_TRICRYPTO:
        a3c: uint256[3] = [0, 0, 0]
        a3c[step.i] = amount
        extcall StablePool3Coins(step.pool).add_liquidity(a3c, 0, value=eth_val)
    elif step.pool_type == constants.POOL_STABLE:
        if step.n_coins == 2:
            a2: uint256[2] = [0, 0]
            a2[step.i] = amount
            extcall StablePool2Coins(step.pool).add_liquidity(
                a2, 0, value=eth_val
            )
        elif step.n_coins == 3:
            a3: uint256[3] = [0, 0, 0]
            a3[step.i] = amount
            if step.variant == constants.LP_VARIANT_LENDING_UNDERLYING:
                extcall LendingStablePool3Coins(step.pool).add_liquidity(
                    a3, 0, True, value=eth_val
                )
            else:
                extcall StablePool3Coins(step.pool).add_liquidity(
                    a3, 0, value=eth_val
                )
        elif step.n_coins == 4:
            a4: uint256[4] = [0, 0, 0, 0]
            a4[step.i] = amount
            extcall StablePool4Coins(step.pool).add_liquidity(
                a4, 0, value=eth_val
            )
        else:
            raw_revert(errors.PoolArityError)
    else:
        raw_revert(errors.AddPoolError)


@internal
def _call_remove_one(step: types.Step, amount: uint256):
    out_token: address = step.token_out

    if (
        step.pool_type == constants.POOL_STABLE
        or step.pool_type == constants.POOL_STABLE_NG
    ):
        if (
            step.pool_type == constants.POOL_STABLE
            and step.n_coins == 3
            and step.variant == constants.LP_VARIANT_LENDING_UNDERLYING
        ):
            extcall LendingStablePool3Coins(
                step.pool
            ).remove_liquidity_one_coin(
                amount,
                convert(step.j, int128),
                0,
                True,
            )
        else:
            extcall StablePool(step.pool).remove_liquidity_one_coin(
                amount,
                convert(step.j, int128),
                0,
            )
    elif step.pool_type == constants.POOL_TRICRYPTO_NG:
        use_eth: bool = out_token == ETH_ADDRESS
        extcall TricryptoNgPool(step.pool).remove_liquidity_one_coin(
            amount,
            step.j,
            0,
            use_eth,
        )
    elif step.pool_type == constants.POOL_TWOCRYPTO_NG:
        extcall TwocryptoNgPool(step.pool).remove_liquidity_one_coin(
            amount,
            step.j,
            0,
            self,
        )
    elif (
        step.pool_type == constants.POOL_TWOCRYPTO
        or step.pool_type == constants.POOL_TRICRYPTO
    ):
        extcall CryptoPool(step.pool).remove_liquidity_one_coin(
            amount,
            step.j,
            0,
        )
    else:
        raw_revert(errors.RemovePoolError)


@internal
def _call_wrap(step: types.Step, amount: uint256):
    in_token: address = step.token_in
    out_token: address = step.token_out

    if step.variant == constants.WRAP_WETH_DEPOSIT:
        errors.require(
            WRAPPED_NATIVE_ADDRESS != empty(address),
            errors.WrapperDisabledError,
        )
        errors.require(
            step.pool == WRAPPED_NATIVE_ADDRESS, errors.WrapperRouteError
        )
        errors.require(in_token == ETH_ADDRESS, errors.WrapperRouteError)
        errors.require(
            out_token == WRAPPED_NATIVE_ADDRESS, errors.WrapperRouteError
        )
        extcall WETH(WRAPPED_NATIVE_ADDRESS).deposit(value=amount)
    elif step.variant == constants.WRAP_WETH_WITHDRAW:
        errors.require(
            WRAPPED_NATIVE_ADDRESS != empty(address),
            errors.WrapperDisabledError,
        )
        errors.require(
            step.pool == WRAPPED_NATIVE_ADDRESS, errors.WrapperRouteError
        )
        errors.require(
            in_token == WRAPPED_NATIVE_ADDRESS, errors.WrapperRouteError
        )
        errors.require(out_token == ETH_ADDRESS, errors.WrapperRouteError)
        extcall WETH(WRAPPED_NATIVE_ADDRESS).withdraw(amount)
    elif step.variant == constants.WRAP_STETH_SUBMIT:
        errors.require(
            STETH_ADDRESS != empty(address), errors.WrapperDisabledError
        )
        errors.require(step.pool == STETH_ADDRESS, errors.WrapperRouteError)
        errors.require(in_token == ETH_ADDRESS, errors.WrapperRouteError)
        errors.require(out_token == STETH_ADDRESS, errors.WrapperRouteError)
        extcall stETH(STETH_ADDRESS).submit(empty(address), value=amount)
    elif step.variant == constants.WRAP_FRXETH_SUBMIT:
        errors.require(
            FRXETH_MINTER_ADDRESS != empty(address), errors.WrapperDisabledError
        )
        errors.require(
            step.pool == FRXETH_MINTER_ADDRESS, errors.WrapperRouteError
        )
        errors.require(in_token == ETH_ADDRESS, errors.WrapperRouteError)
        errors.require(
            out_token == FRXETH_TOKEN_ADDRESS, errors.WrapperRouteError
        )
        extcall frxETHMinter(FRXETH_MINTER_ADDRESS).submit(value=amount)
    elif step.variant == constants.WRAP_WSTETH_WRAP:
        errors.require(
            WSTETH_ADDRESS != empty(address), errors.WrapperDisabledError
        )
        errors.require(step.pool == WSTETH_ADDRESS, errors.WrapperRouteError)
        errors.require(in_token == STETH_ADDRESS, errors.WrapperRouteError)
        errors.require(out_token == WSTETH_ADDRESS, errors.WrapperRouteError)
        self._lazy_approve(in_token, WSTETH_ADDRESS)
        extcall wstETH(WSTETH_ADDRESS).wrap(amount)
    elif step.variant == constants.WRAP_WSTETH_UNWRAP:
        errors.require(
            WSTETH_ADDRESS != empty(address), errors.WrapperDisabledError
        )
        errors.require(step.pool == WSTETH_ADDRESS, errors.WrapperRouteError)
        errors.require(in_token == WSTETH_ADDRESS, errors.WrapperRouteError)
        errors.require(out_token == STETH_ADDRESS, errors.WrapperRouteError)
        extcall wstETH(WSTETH_ADDRESS).unwrap(amount)
    elif step.variant == constants.WRAP_4626_DEPOSIT:
        errors.require(step.pool == out_token, errors.WrapperRouteError)
        self._lazy_approve(in_token, step.pool)
        extcall ERC4626(step.pool).deposit(amount, self)
    elif step.variant == constants.WRAP_4626_REDEEM:
        errors.require(step.pool == in_token, errors.WrapperRouteError)
        extcall ERC4626(step.pool).redeem(amount, self, self)
    elif step.variant == constants.WRAP_AMOUNT_CALL_DEPOSIT:
        errors.require(step.pool != empty(address), errors.WrapperRouteError)
        errors.require(in_token != ETH_ADDRESS, errors.WrapperRouteError)
        errors.require(out_token != ETH_ADDRESS, errors.WrapperRouteError)
        self._lazy_approve(in_token, step.pool)
        extcall AmountCallAdapter(step.pool).deposit(amount)
    elif step.variant == constants.WRAP_AMOUNT_CALL_WITHDRAW:
        errors.require(step.pool != empty(address), errors.WrapperRouteError)
        errors.require(in_token != ETH_ADDRESS, errors.WrapperRouteError)
        errors.require(out_token != ETH_ADDRESS, errors.WrapperRouteError)
        self._lazy_approve(in_token, step.pool)
        extcall AmountCallAdapter(step.pool).withdraw(amount)
    else:
        raw_revert(errors.WrapperRouteError)


@internal
def _remove_balanced(root: types.BalancedRoot, amount: uint256) -> uint256[8]:
    errors.require(
        root.n_coins >= 2 and root.n_coins <= 8, errors.BalancedRootError
    )

    before: uint256[8] = empty(uint256[8])
    for k: uint256 in range(8):
        if k >= root.n_coins:
            break
        errors.require(
            root.coins[k] != empty(address), errors.BalancedRootError
        )
        for prev: uint256 in range(8):
            if prev >= k:
                break
            errors.require(
                root.coins[prev] != root.coins[k], errors.BalancedRootError
            )
        before[k] = self._bal(root.coins[k])

    if root.pool_type == constants.POOL_STABLE_NG:
        mins_ng: DynArray[uint256, 8] = self._zero_amounts_ng(root.n_coins)
        extcall StableNgPool(root.pool).remove_liquidity(amount, mins_ng)
    elif root.pool_type == constants.POOL_TRICRYPTO_NG:
        extcall TricryptoNgPool(root.pool).remove_liquidity(
            amount, [0, 0, 0], True
        )
    elif root.pool_type == constants.POOL_TWOCRYPTO_NG:
        extcall TwocryptoNgPool(root.pool).remove_liquidity(
            amount, [0, 0], self
        )
    elif root.pool_type == constants.POOL_TWOCRYPTO:
        extcall StablePool2Coins(root.pool).remove_liquidity(amount, [0, 0])
    elif root.pool_type == constants.POOL_TRICRYPTO:
        extcall StablePool3Coins(root.pool).remove_liquidity(amount, [0, 0, 0])
    elif root.pool_type == constants.POOL_STABLE:
        if root.n_coins == 2:
            extcall StablePool2Coins(root.pool).remove_liquidity(amount, [0, 0])
        elif root.n_coins == 3:
            extcall StablePool3Coins(root.pool).remove_liquidity(
                amount, [0, 0, 0]
            )
        elif root.n_coins == 4:
            extcall StablePool4Coins(root.pool).remove_liquidity(
                amount, [0, 0, 0, 0]
            )
        else:
            raw_revert(errors.PoolArityError)
    else:
        raw_revert(errors.BalancedPoolError)

    deltas: uint256[8] = empty(uint256[8])
    saw_out: bool = False
    for k2: uint256 in range(8):
        if k2 >= root.n_coins:
            break
        delta: uint256 = self._bal(root.coins[k2]) - before[k2]
        deltas[k2] = delta
        if delta > 0:
            saw_out = True
    errors.require(saw_out, errors.ZeroOutputError)
    return deltas


@payable
@external
@nonreentrant
def execute_linear_exact_in(
    steps: DynArray[types.Step, constants.MAX_LINEAR_STEPS],
    initial_token: address,
    amount_in: uint256,
    final_token: address,
    min_out: uint256,
    receiver: address = msg.sender,
) -> uint256:
    actual_in: uint256 = self._settle_input(initial_token, amount_in, msg.value)

    token: address = initial_token
    out_amount: uint256 = actual_in
    if len(steps) > 0:
        route: types.RouteSlice = types.RouteSlice(
            step_start=0, step_count=len(steps)
        )
        token, out_amount = self._execute_route(
            steps, route, initial_token, actual_in
        )

    errors.require(token == final_token, errors.FinalTokenError)
    errors.require(out_amount >= min_out, errors.SlippageError)
    self._payout(final_token, out_amount, receiver)

    log Exchange(
        sender=msg.sender,
        receiver=receiver,
        token_in=initial_token,
        token_out=final_token,
        amount_in=amount_in,
        amount_out=out_amount,
    )
    return out_amount


@payable
@external
@nonreentrant
def execute_split_exact_in(
    branches: DynArray[types.SplitBranch, constants.MAX_SPLIT_BRANCHES],
    steps: DynArray[types.Step, constants.MAX_LINEAR_STEPS],
    initial_token: address,
    amount_in: uint256,
    final_token: address,
    min_out: uint256,
    receiver: address = msg.sender,
) -> uint256:
    errors.require(len(branches) > 0, errors.SplitRouteError)
    actual_in: uint256 = self._settle_input(initial_token, amount_in, msg.value)

    nominal_total: uint256 = 0
    for i: uint256 in range(constants.MAX_SPLIT_BRANCHES):
        if i >= len(branches):
            break
        nominal_total += branches[i].amount_in
    errors.require(nominal_total > 0, errors.SplitRouteError)

    total_out: uint256 = 0
    allocated: uint256 = 0
    last_branch: uint256 = len(branches) - 1

    for j: uint256 in range(constants.MAX_SPLIT_BRANCHES):
        if j >= len(branches):
            break

        branch_amount: uint256 = 0
        if j == last_branch:
            branch_amount = actual_in - allocated
        else:
            branch_amount = actual_in * branches[j].amount_in // nominal_total
            allocated += branch_amount

        token: address = initial_token
        out_amount: uint256 = branch_amount
        if branches[j].route.step_count > 0 and branch_amount > 0:
            token, out_amount = self._execute_route(
                steps,
                branches[j].route,
                initial_token,
                branch_amount,
            )
        errors.require(token == final_token, errors.FinalTokenError)
        total_out += out_amount
    errors.require(total_out >= min_out, errors.SlippageError)
    self._payout(final_token, total_out, receiver)

    log Exchange(
        sender=msg.sender,
        receiver=receiver,
        token_in=initial_token,
        token_out=final_token,
        amount_in=amount_in,
        amount_out=total_out,
    )
    return total_out


@payable
@external
@nonreentrant
def execute_balanced_exact_in(
    root: types.BalancedRoot,
    branches: DynArray[types.BalancedBranch, constants.MAX_BALANCED_BRANCHES],
    steps: DynArray[types.Step, constants.MAX_LINEAR_STEPS],
    amount_in: uint256,
    final_token: address,
    min_out: uint256,
    receiver: address = msg.sender,
) -> uint256:
    errors.require(len(branches) == root.n_coins, errors.BalancedRootError)
    actual_in: uint256 = self._settle_input(root.lp_token, amount_in, msg.value)
    outputs: uint256[8] = self._remove_balanced(root, actual_in)

    total_out: uint256 = 0
    for k: uint256 in range(constants.MAX_BALANCED_BRANCHES):
        if k >= root.n_coins:
            break
        branch_amount: uint256 = outputs[k]
        if branch_amount == 0:
            continue
        if branches[k].route.step_count == 0:
            errors.require(root.coins[k] == final_token, errors.FinalTokenError)
            total_out += branch_amount
        else:
            token: address = root.coins[k]
            out_amount: uint256 = branch_amount
            token, out_amount = self._execute_route(
                steps,
                branches[k].route,
                token,
                branch_amount,
            )
            errors.require(token == final_token, errors.FinalTokenError)
            total_out += out_amount
    errors.require(total_out >= min_out, errors.SlippageError)
    self._payout(final_token, total_out, receiver)

    log Exchange(
        sender=msg.sender,
        receiver=receiver,
        token_in=root.lp_token,
        token_out=final_token,
        amount_in=amount_in,
        amount_out=total_out,
    )
    return total_out
